import { test, expect } from '@playwright/test';

test.describe('User Profile Picture Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user-profile');
  });

  test('should allow user to upload a profile picture', async ({ page }) => {
    const filePath = 'path/to/profile-picture.jpg';
    await page.getByLabel('Upload Profile Picture').setInputFiles(filePath);
    await expect(page.getByText('Profile picture uploaded successfully')).toBeVisible();
  });

  test('should display the uploaded profile picture preview', async ({ page }) => {
    const filePath = 'path/to/profile-picture.jpg';
    await page.getByLabel('Upload Profile Picture').setInputFiles(filePath);
    await expect(page.getByRole('img', { name: 'Profile Picture Preview' })).toHaveAttribute('src', /profile-picture.jpg/);
  });
});
